function bind(id,fn){document.getElementById(id).onclick=fn;}function openPanel(n){document.querySelectorAll(".tab,.panel").forEach(e=>e.classList.remove("active"));document.querySelector(`[data-panel="${n}"]`).classList.add("active");document.getElementById(`panel-${n}`).classList.add("active");if(n==="duplicates"||n==="compare")loadColumnControls();if(n==="history")renderHistory();if(n==="desktop-pro")detectEnvironment();}
function setLanguage(lang){localStorage.setItem("eda-lang",lang);document.documentElement.lang=lang;document.getElementById("language").value=lang;document.querySelectorAll("[data-i18n]").forEach(e=>{const v=I18N[lang]?.[e.dataset.i18n]||I18N.ru[e.dataset.i18n];if(v)e.textContent=v;});renderHistory();setStatus(I18N[lang].ready);}
function requireSize(r){const cells=r.rowCount*r.columnCount;if(cells>MAX_CELLS)throw new Error(`Диапазон слишком велик: ${cells.toLocaleString()} ячеек. Лимит: ${MAX_CELLS.toLocaleString()}.`);return cells;}
async function analyze(){await run("Анализ",async c=>{progress(10);const r=c.workbook.getSelectedRange();r.load(["address","values","valueTypes","formulas","rowCount","columnCount"]);await c.sync();const cells=requireSize(r),v=r.values.flat(),t=r.valueTypes.flat(),f=r.formulas.flat();progress(55);const nums=v.filter((x,i)=>t[i]===Excel.RangeValueType.double&&Number.isFinite(x)),sorted=[...nums].sort((a,b)=>a-b),sum=nums.reduce((a,b)=>a+b,0),filled=v.filter((_x,i)=>t[i]!==Excel.RangeValueType.empty);const stats={sum:nums.length?sum:null,average:nums.length?sum/nums.length:null,median:median(sorted),min:nums.length?sorted[0]:null,max:nums.length?sorted.at(-1):null,numbers:nums.length,text:t.filter(x=>x===Excel.RangeValueType.string).length,formulas:f.filter(x=>typeof x==="string"&&x.startsWith("=")).length,empty:t.filter(x=>x===Excel.RangeValueType.empty).length,unique:new Set(filled.map(keyValue)).size,errors:t.filter(x=>x===Excel.RangeValueType.error).length};Object.entries(stats).forEach(([k,x])=>document.getElementById(`metric-${k}`).textContent=x===null?"—":nf.format(x));document.getElementById("analysis-address").textContent=r.address;document.getElementById("analysis-size").textContent=`${r.rowCount} × ${r.columnCount} · ${cells} ячеек`;document.getElementById("analysis-results").classList.remove("hidden");progress(100);setStatus(`Диапазон ${r.address} проанализирован.`);});}

async function loadColumnControls(){await run(null,async c=>{const r=c.workbook.getSelectedRange();r.load(["values","columnCount"]);await c.sync();const headers=r.values[0]||[];const dup=document.getElementById("duplicate-columns"),sel=document.getElementById("compare-key");dup.innerHTML="";sel.innerHTML="";for(let i=0;i<r.columnCount;i++){const name=String(headers[i]||`Столбец ${i+1}`);const l=document.createElement("label");l.innerHTML=`<input type="checkbox" value="${i}" checked> ${escapeHtml(name)}`;dup.appendChild(l);const o=document.createElement("option");o.value=i;o.textContent=name;sel.appendChild(o);}});}
async function clean(apply){await run(apply?"Очистка":"Предпросмотр очистки",async c=>{const r=c.workbook.getSelectedRange();r.load(["address","values","formulas","rowCount","columnCount"]);await c.sync();requireSize(r);const original=r.values,formulas=r.formulas,isFormula=(i,j)=>typeof formulas[i][j]==="string"&&formulas[i][j].startsWith("="),cleaned=original.map((row,i)=>row.map((v,j)=>isFormula(i,j)?v:cleanValue(v))),output=cleaned.map((row,i)=>row.map((v,j)=>isFormula(i,j)?formulas[i][j]:v));const removeEmpty=document.getElementById("clean-empty-rows").checked,keep=cleaned.map(row=>!removeEmpty||row.some(v=>v!==""&&v!==null)),final=output.filter((_row,i)=>keep[i]);let changed=0;original.forEach((row,i)=>row.forEach((v,j)=>{if(String(v)!==String(cleaned[i][j]))changed++;}));const removed=keep.filter(x=>!x).length;show("clean-preview",`Изменяемых ячеек: ${changed}\nПустых строк: ${removed}\nФормулы сохранены: ${formulas.flat().filter(x=>typeof x==="string"&&x.startsWith("=")).length}`);if(!apply)return;const b=await backup(c,r,"Резерв_очистка");r.clear("Contents");if(final.length)r.getCell(0,0).getResizedRange(final.length-1,r.columnCount-1).formulas=final;await c.sync();show("clean-preview",`Готово. Изменено: ${changed}; удалено строк: ${removed}.\nРезерв: ${b.sheet}`);});}
function cleanValue(v){if(typeof v!=="string")return v;let x=v;if(document.getElementById("clean-nonprinting").checked)x=x.replace(/[\x00-\x1F\x7F]/g,"");if(document.getElementById("clean-trim").checked)x=x.replace(/\s+/g," ").trim();const m=document.getElementById("clean-case").value;if(m==="upper")x=x.toLocaleUpperCase();if(m==="lower")x=x.toLocaleLowerCase();if(m==="title")x=x.toLocaleLowerCase().replace(/(^|\s)\p{L}/gu,z=>z.toLocaleUpperCase());return x;}

async function duplicates(mode){await run(`Дубликаты: ${mode}`,async c=>{const r=c.workbook.getSelectedRange();r.load(["address","values","formulas","rowCount","columnCount"]);await c.sync();requireSize(r);const cols=[...document.querySelectorAll("#duplicate-columns input:checked")].map(x=>+x.value);if(!cols.length)throw new Error("Выберите хотя бы один столбец.");const seen=new Map(),dupes=[];r.values.forEach((row,i)=>{const k=JSON.stringify(cols.map(j=>keyValue(row[j])));if(seen.has(k))dupes.push({row:i,first:seen.get(k)});else seen.set(k,i);});show("duplicate-result",`Повторных строк: ${dupes.length}\nСтрок для сохранения: ${r.rowCount-dupes.length}`);if(mode==="preview")return;if(mode==="highlight"){dupes.forEach(x=>r.getRow(x.row).format.fill.color="#FFD966");await c.sync();return;}const b=await backup(c,r,"Резерв_дубликаты"),remove=new Set(dupes.map(x=>x.row)),unique=r.formulas.filter((_x,i)=>!remove.has(i));r.clear("Contents");if(unique.length)r.getCell(0,0).getResizedRange(unique.length-1,r.columnCount-1).formulas=unique;await c.sync();show("duplicate-result",`Удалено: ${dupes.length}\nФормулы сохранены: ${unique.flat().filter(x=>typeof x==="string"&&x.startsWith("=")).length}\nРезерв: ${b.sheet}`);});}

async function saveFirst(){await run("Сохранение первой таблицы",async c=>{const r=c.workbook.getSelectedRange();r.load(["address","values","formulas","numberFormat","rowCount","columnCount"]);await c.sync();requireSize(r);const key=+document.getElementById("compare-key").value;firstSnapshot={address:r.address,values:r.values,formulas:r.formulas,formats:r.numberFormat,key};const d=findDuplicateKeys(r.values.slice(1),key);show("compare-result",`Первая таблица: ${r.address}\nСтрок данных: ${Math.max(0,r.rowCount-1)}\nПовторяющихся ключей: ${d.length}${d.length?`\n${d.slice(0,10).join(", ")}`:""}`);});}
async function compare(){if(!firstSnapshot){setStatus("Сначала сохраните первую таблицу.",true);return;}await run("Сверка",async c=>{const r=c.workbook.getSelectedRange();r.load(["address","values","rowCount","columnCount"]);await c.sync();requireSize(r);const a=firstSnapshot.values,b=r.values,key=firstSnapshot.key;if(a.length<2||b.length<2)throw new Error("Нужны заголовки и данные.");const dupA=findDuplicateKeys(a.slice(1),key),dupB=findDuplicateKeys(b.slice(1),key);if(dupA.length||dupB.length)throw new Error(`Сверка остановлена: повторяющиеся ключи. Таблица 1: ${dupA.length}; таблица 2: ${dupB.length}.`);const cs=document.getElementById("compare-case-sensitive").checked,mapA=new Map(a.slice(1).map(x=>[keyValue(x[key],cs),x])),mapB=new Map(b.slice(1).map(x=>[keyValue(x[key],cs),x])),width=Math.max(a[0].length,b[0].length),rows=[["Статус","Ключ",...padHeaders(a[0],width,"A"),...padHeaders(b[0],width,"B")]];for(const [k,x] of mapA){const y=mapB.get(k);rows.push([!y?"Только в первой":rowKey(x,cs)===rowKey(y,cs)?"Совпадает":"Изменено",x[key],...pad(x,width),...pad(y||[],width)]);}for(const [k,y] of mapB)if(!mapA.has(k))rows.push(["Только во второй",y[key],...pad([],width),...pad(y,width)]);const ws=c.workbook.worksheets.add(sheetName("Сверка"));ws.load("name");const out=ws.getRangeByIndexes(0,0,rows.length,rows[0].length);out.values=rows;styleHeader(out.getRow(0));out.format.autofitColumns();ws.activate();await c.sync();const counts=rows.slice(1).reduce((o,x)=>(o[x[0]]=(o[x[0]]||0)+1,o),{});show("compare-result",Object.entries(counts).map(([k,v])=>`${k}: ${v}`).join("\n")+`\nЛист: ${ws.name}`);});}

async function report(){await run("Создание отчёта",async c=>{const r=c.workbook.getSelectedRange();r.load(["address","values","formulas","numberFormat","rowCount","columnCount"]);await c.sync();requireSize(r);const hasHeader=document.getElementById("report-first-row-header").checked;if(r.rowCount<(hasHeader?2:1))throw new Error("Недостаточно данных.");const headers=hasHeader?r.values[0]:Array.from({length:r.columnCount},(_,i)=>`Столбец ${i+1}`),data=hasHeader?r.values.slice(1):r.values,forms=hasHeader?r.formulas.slice(1):r.formulas,formats=hasHeader?r.numberFormat.slice(1):r.numberFormat;const summary=[],typeRows=[];headers.forEach((h,i)=>{const vals=data.map(x=>x[i]),nums=vals.filter(Number.isFinite),formulaCount=forms.map(x=>x[i]).filter(x=>typeof x==="string"&&x.startsWith("=")).length,fmt=formats[0]?.[i]||"General",type=inferType(vals,fmt);typeRows.push([String(h),type,formulaCount,vals.filter(x=>x===""||x===null).length]);if(nums.length){const sum=nums.reduce((a,b)=>a+b,0);summary.push([String(h),nums.length,sum,sum/nums.length,Math.min(...nums),Math.max(...nums),fmt]);}});const ws=c.workbook.worksheets.add(sheetName("Отчёт"));ws.load("name");const intro=[["ОТЧЁТ ПО ДАННЫМ",r.address],["Строк данных",data.length],["Столбцов",r.columnCount],["Формул",forms.flat().filter(x=>typeof x==="string"&&x.startsWith("=")).length],["Создан",new Date().toLocaleString()]];ws.getRangeByIndexes(0,0,intro.length,2).values=intro;styleHeader(ws.getRange("A1:B1"));const s=7,sRows=[["Столбец","Количество","Сумма","Среднее","Минимум","Максимум","Формат"],...summary];ws.getRangeByIndexes(s,0,sRows.length,7).values=sRows;styleHeader(ws.getRangeByIndexes(s,0,1,7));const t=s+sRows.length+2,tRows=[["Столбец","Тип","Формулы","Пустые"],...typeRows];ws.getRangeByIndexes(t,0,tRows.length,4).values=tRows;styleHeader(ws.getRangeByIndexes(t,0,1,4));if(document.getElementById("report-chart").checked&&summary.length){const chart=ws.charts.add("ColumnClustered",ws.getRangeByIndexes(s,0,sRows.length,3));chart.title.text="Суммы по числовым столбцам";chart.setPosition("I2","Q18");}ws.getUsedRange().format.autofitColumns();ws.activate();await c.sync();show("report-result",`Отчёт: ${ws.name}\nЧисловых столбцов: ${summary.length}\nВсего типов: ${typeRows.length}`);});}

async function fillBlanks(){await run("Заполнение пустых",async c=>{const r=c.workbook.getSelectedRange();r.load(["address","values","formulas","rowCount","columnCount"]);await c.sync();requireSize(r);const out=r.formulas.map(row=>[...row]),dir=document.getElementById("fill-direction").value,isBlank=v=>v===""||v===null,rows=r.rowCount,cols=r.columnCount;let changed=0;if(dir==="down")for(let j=0;j<cols;j++)for(let i=1;i<rows;i++)if(isBlank(out[i][j])&&!isBlank(out[i-1][j])){out[i][j]=out[i-1][j];changed++;}if(dir==="up")for(let j=0;j<cols;j++)for(let i=rows-2;i>=0;i--)if(isBlank(out[i][j])&&!isBlank(out[i+1][j])){out[i][j]=out[i+1][j];changed++;}if(dir==="right")for(let i=0;i<rows;i++)for(let j=1;j<cols;j++)if(isBlank(out[i][j])&&!isBlank(out[i][j-1])){out[i][j]=out[i][j-1];changed++;}if(dir==="left")for(let i=0;i<rows;i++)for(let j=cols-2;j>=0;j--)if(isBlank(out[i][j])&&!isBlank(out[i][j+1])){out[i][j]=out[i][j+1];changed++;}const b=await backup(c,r,"Резерв_пустые");r.formulas=out;await c.sync();show("cells-result",`Заполнено ячеек: ${changed}\nРезерв: ${b.sheet}`);});}

async function selectByCondition(){await run("Выделение по условию",async c=>{const r=c.workbook.getSelectedRange();r.load(["values","valueTypes","formulas","rowCount","columnCount"]);await c.sync();requireSize(r);const type=document.getElementById("condition-type").value,arg=document.getElementById("condition-value").value,matches=[];for(let i=0;i<r.rowCount;i++)for(let j=0;j<r.columnCount;j++){const v=r.values[i][j],f=r.formulas[i][j],vt=r.valueTypes[i][j];let ok=type==="empty"?(v===""||v===null):type==="nonempty"?(v!==""&&v!==null):type==="text"?String(v).toLocaleLowerCase().includes(arg.toLocaleLowerCase()):type==="gt"?Number(v)>Number(arg):type==="lt"?Number(v)<Number(arg):type==="formula"?(typeof f==="string"&&f.startsWith("=")):vt===Excel.RangeValueType.error;if(ok)matches.push(r.getCell(i,j));}matches.forEach(x=>x.format.fill.color="#FFF2CC");if(matches.length)matches[0].select();await c.sync();show("cells-result",`Найдено и подсвечено: ${matches.length}`);});}

async function processText(){await run("Обработка текста",async c=>{const r=c.workbook.getSelectedRange();r.load(["address","values","formulas","rowCount","columnCount"]);await c.sync();requireSize(r);const op=document.getElementById("text-operation").value,out=r.formulas.map(row=>[...row]);let changed=0,latin=0;for(let i=0;i<r.rowCount;i++)for(let j=0;j<r.columnCount;j++){if(typeof r.formulas[i][j]==="string"&&r.formulas[i][j].startsWith("="))continue;const v=r.values[i][j];if(typeof v!=="string")continue;if(op==="latin"){if(/[A-Za-z]/.test(v)){r.getCell(i,j).format.fill.color="#F4CCCC";latin++;}continue;}let n=op==="trim"?v.replace(/\s+/g," ").trim():op==="upper"?v.toLocaleUpperCase():op==="lower"?v.toLocaleLowerCase():op==="title"?v.toLocaleLowerCase().replace(/(^|\s)\p{L}/gu,x=>x.toLocaleUpperCase()):op==="remove-digits"?v.replace(/\d/g,""):v.replace(/\p{L}/gu,"");if(n!==v){out[i][j]=n;changed++;}}if(op!=="latin"){const b=await backup(c,r,"Резерв_текст");r.formulas=out;show("cells-result",`Изменено: ${changed}\nРезерв: ${b.sheet}`);}else show("cells-result",`Ячеек с латиницей: ${latin}`);await c.sync();});}

async function createDropdown(){await run("Выпадающий список",async c=>{const r=c.workbook.getSelectedRange(),items=document.getElementById("dropdown-values").value.split(";").map(x=>x.trim()).filter(Boolean);if(!items.length)throw new Error("Введите пункты через точку с запятой.");r.dataValidation.rule={list:{inCellDropDown:true,source:items.join(",")}};await c.sync();show("cells-result",`Создан список: ${items.join(", ")}`);});}

async function generateTestData(){await run("Генерация тестовых данных",async c=>{const ws=c.workbook.worksheets.add(sheetName("Тестовые_данные")),rows=[["ID","Имя","Сумма","Дата","Процент","Категория"],[1,"  Alpha  ",100,"01.08.2026",.1,"A"],[2,"Beta",200.5,"02.08.2026",.25,"B"],[2,"Beta",200.5,"02.08.2026",.25,"B"],[3," gamma ","","03.08.2026",.5,"A"],[4,"ALPHA",-50,"04.08.2026",0,"C"]];ws.load("name");const r=ws.getRangeByIndexes(0,0,rows.length,rows[0].length);r.values=rows;styleHeader(r.getRow(0));ws.getRange("E2:E6").numberFormat=Array.from({length:5},()=>["0.0%"]);r.format.autofitColumns();ws.activate();await c.sync();show("cells-result",`Создан лист: ${ws.name}`);});}

async function changeReferences(){await run("Изменение ссылок",async c=>{const r=c.workbook.getSelectedRange();r.load(["address","formulas","rowCount","columnCount"]);await c.sync();const mode=document.getElementById("reference-style").value,out=r.formulas.map(row=>[...row]);let changed=0;const re=/\$?([A-Z]{1,3})\$?(\d+)/g;for(let i=0;i<r.rowCount;i++)for(let j=0;j<r.columnCount;j++){const f=out[i][j];if(typeof f!=="string"||!f.startsWith("="))continue;out[i][j]=f.replace(re,(_m,col,row)=>mode==="absolute"?`$${col}$${row}`:mode==="row"?`${col}$${row}`:mode==="column"?`$${col}${row}`:`${col}${row}`);changed++;}const b=await backup(c,r,"Резерв_ссылки");r.formulas=out;await c.sync();show("formula-result",`Обновлено формул: ${changed}\nРезерв: ${b.sheet}`);});}

async function wrapIfError(){await run("Добавление IFERROR",async c=>{const r=c.workbook.getSelectedRange();r.load(["address","formulas","rowCount","columnCount"]);await c.sync();const fallback=document.getElementById("iferror-value").value||"0",fallbackExpr=fallback.trim()!==""&&Number.isFinite(Number(fallback))?String(Number(fallback)):JSON.stringify(fallback),out=r.formulas.map(row=>[...row]);let changed=0;for(let i=0;i<r.rowCount;i++)for(let j=0;j<r.columnCount;j++){const f=out[i][j];if(typeof f==="string"&&f.startsWith("=")&&!/^=IFERROR\(/i.test(f)){out[i][j]=`=IFERROR(${f.slice(1)},${fallbackExpr})`;changed++;}}const b=await backup(c,r,"Резерв_IFERROR");r.formulas=out;await c.sync();show("formula-result",`Обёрнуто формул: ${changed}\nРезерв: ${b.sheet}`);});}

async function copyFormulasExact(){await run("Копирование формул",async c=>{const r=c.workbook.getSelectedRange();r.load(["formulas","rowCount","columnCount"]);await c.sync();exactFormulaSnapshot={formulas:r.formulas,rows:r.rowCount,cols:r.columnCount};show("formula-result",`Скопировано: ${r.rowCount} × ${r.columnCount}`);});}
async function pasteFormulasExact(){if(!exactFormulaSnapshot){setStatus("Сначала сохраните точную копию.",true);return;}await run("Вставка формул",async c=>{const r=c.workbook.getSelectedRange(),target=r.getCell(0,0).getResizedRange(exactFormulaSnapshot.rows-1,exactFormulaSnapshot.cols-1);target.formulas=exactFormulaSnapshot.formulas;await c.sync();show("formula-result",`Вставлено: ${exactFormulaSnapshot.rows} × ${exactFormulaSnapshot.cols}`);});}
async function formulaMap(){await run("Карта формул",async c=>{const r=c.workbook.getSelectedRange();r.load(["formulas","valueTypes","rowCount","columnCount"]);await c.sync();let formulas=0,errors=0;for(let i=0;i<r.rowCount;i++)for(let j=0;j<r.columnCount;j++){const cell=r.getCell(i,j);if(typeof r.formulas[i][j]==="string"&&r.formulas[i][j].startsWith("=")){cell.format.fill.color="#D9EAD3";formulas++;}if(r.valueTypes[i][j]===Excel.RangeValueType.error){cell.format.fill.color="#F4CCCC";errors++;}}await c.sync();show("formula-result",`Формулы: ${formulas}; ошибки: ${errors}`);});}

async function unpivotTable(){await run("Нормализация",async c=>{const r=c.workbook.getSelectedRange();r.load(["address","values","rowCount","columnCount"]);await c.sync();const keys=Math.max(1,+document.getElementById("unpivot-keys").value),v=r.values;if(v.length<2||keys>=r.columnCount)throw new Error("Недостаточно данных для нормализации.");const out=[[...v[0].slice(0,keys),"Атрибут","Значение"]];for(let i=1;i<v.length;i++)for(let j=keys;j<r.columnCount;j++)out.push([...v[i].slice(0,keys),v[0][j],v[i][j]]);const ws=c.workbook.worksheets.add(sheetName("Нормализация"));ws.load("name");const o=ws.getRangeByIndexes(0,0,out.length,out[0].length);o.values=out;styleHeader(o.getRow(0));o.format.autofitColumns();ws.activate();await c.sync();show("transform-result",`Создано строк: ${out.length-1}\nЛист: ${ws.name}`);});}

async function pivotTable(){await run("Свёртка",async c=>{const r=c.workbook.getSelectedRange();r.load(["values","rowCount","columnCount"]);await c.sync();const ri=+document.getElementById("pivot-row").value-1,ci=+document.getElementById("pivot-column").value-1,vi=+document.getElementById("pivot-value").value-1,v=r.values;if(v.length<2||[ri,ci,vi].some(x=>x<0||x>=r.columnCount))throw new Error("Проверьте номера столбцов.");const cats=[...new Set(v.slice(1).map(x=>String(x[ci])))],keys=[...new Set(v.slice(1).map(x=>String(x[ri])))],map=new Map(v.slice(1).map(x=>[`${x[ri]}\u0000${x[ci]}`,x[vi]])),out=[[v[0][ri],...cats],...keys.map(k=>[k,...cats.map(cat=>map.get(`${k}\u0000${cat}`)??"")])];const ws=c.workbook.worksheets.add(sheetName("Свёртка"));ws.load("name");const o=ws.getRangeByIndexes(0,0,out.length,out[0].length);o.values=out;styleHeader(o.getRow(0));o.format.autofitColumns();ws.activate();await c.sync();show("transform-result",`Размер: ${out.length} × ${out[0].length}\nЛист: ${ws.name}`);});}

async function reorderRows(mode){await run(mode==="reverse"?"Обратный порядок":"Случайный порядок",async c=>{const r=c.workbook.getSelectedRange();r.load(["address","formulas","rowCount","columnCount"]);await c.sync();if(r.rowCount<2)throw new Error("Нужно минимум две строки.");const head=r.formulas[0],data=r.formulas.slice(1);if(mode==="reverse")data.reverse();else for(let i=data.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[data[i],data[j]]=[data[j],data[i]];}const b=await backup(c,r,"Резерв_порядок");r.formulas=[head,...data];await c.sync();show("transform-result",`Переставлено строк: ${data.length}\nРезерв: ${b.sheet}`);});}

async function filterAction(){await run("Фильтр + действие",async c=>{const r=c.workbook.getSelectedRange();r.load(["address","values","formulas","rowCount","columnCount"]);await c.sync();const col=+document.getElementById("filter-column").value-1,needle=document.getElementById("filter-value").value.toLocaleLowerCase(),action=document.getElementById("filter-action").value;if(col<0||col>=r.columnCount)throw new Error("Неверный номер столбца.");const hits=r.values.map((row,i)=>i>0&&String(row[col]).toLocaleLowerCase().includes(needle)),picked=[r.formulas[0],...r.formulas.filter((_x,i)=>hits[i])],rest=r.formulas.filter((_x,i)=>!hits[i]);if(action==="copy"||action==="move"){const ws=c.workbook.worksheets.add(sheetName("Фильтр"));ws.getRangeByIndexes(0,0,picked.length,picked[0].length).formulas=picked;ws.getUsedRange().format.autofitColumns();}if(action==="delete"||action==="move"){const b=await backup(c,r,"Резерв_фильтр");r.clear("Contents");r.getCell(0,0).getResizedRange(rest.length-1,r.columnCount-1).formulas=rest;lastBackup=b;}await c.sync();show("data-tools-result",`Совпадений: ${picked.length-1}; действие: ${action}`);});}

async function removeIncellDuplicates(){await run("Повторы внутри ячеек",async c=>{const r=c.workbook.getSelectedRange();r.load(["address","values","formulas","rowCount","columnCount"]);await c.sync();const sep=document.getElementById("incell-separator").value||",",out=r.formulas.map(row=>[...row]);let changed=0;for(let i=0;i<r.rowCount;i++)for(let j=0;j<r.columnCount;j++){if(typeof r.formulas[i][j]==="string"&&r.formulas[i][j].startsWith("="))continue;const v=r.values[i][j];if(typeof v!=="string"||!v.includes(sep))continue;const seen=new Set(),parts=v.split(sep).map(x=>x.trim()).filter(x=>{const k=x.toLocaleLowerCase();if(seen.has(k))return false;seen.add(k);return true;}),n=parts.join(`${sep} `);if(n!==v){out[i][j]=n;changed++;}}const b=await backup(c,r,"Резерв_повторы");r.formulas=out;await c.sync();show("data-tools-result",`Изменено ячеек: ${changed}\nРезерв: ${b.sheet}`);});}

async function colorMap(){await run("Цветовая карта",async c=>{const r=c.workbook.getSelectedRange();r.load(["valueTypes","formulas","rowCount","columnCount"]);await c.sync();for(let i=0;i<r.rowCount;i++)for(let j=0;j<r.columnCount;j++){const f=r.formulas[i][j],t=r.valueTypes[i][j],color=typeof f==="string"&&f.startsWith("=")?"#D9EAD3":t===Excel.RangeValueType.double?"#CFE2F3":t===Excel.RangeValueType.string?"#FFF2CC":t===Excel.RangeValueType.error?"#F4CCCC":"#EEEEEE";r.getCell(i,j).format.fill.color=color;}await c.sync();show("data-tools-result","Цвета: формулы — зелёный, числа — синий, текст — жёлтый, ошибки — красный.");});}

async function exportCsv(){await run("Экспорт CSV",async c=>{const r=c.workbook.getSelectedRange();r.load(["values","address"]);await c.sync();const csv=r.values.map(row=>row.map(v=>`"${String(v??"").replace(/"/g,'""')}"`).join(";")).join("\r\n"),blob=new Blob(["\uFEFF",csv],{type:"text/csv;charset=utf-8"}),a=document.createElement("a");a.href=URL.createObjectURL(blob);a.download=`excel-export-${Date.now()}.csv`;a.click();URL.revokeObjectURL(a.href);show("data-tools-result",`Экспортирован диапазон ${r.address}`);});}

async function createToc(){await run("Оглавление книги",async c=>{const sheets=c.workbook.worksheets;sheets.load("items/name");await c.sync();const ws=sheets.add(sheetName("Оглавление")),rows=[["Лист","Ссылка"],...sheets.items.map(x=>[x.name,`Перейти: ${x.name}`])],r=ws.getRangeByIndexes(0,0,rows.length,2);r.values=rows;styleHeader(r.getRow(0));for(let i=1;i<rows.length;i++)r.getCell(i,1).hyperlink={address:"",documentReference:`'${rows[i][0].replace(/'/g,"''")}'!A1`,textToDisplay:"Открыть"};r.format.autofitColumns();ws.activate();await c.sync();show("sheets-result",`Добавлено листов: ${rows.length-1}`);});}

async function collectSheets(){await run("Сбор листов",async c=>{const sheets=c.workbook.worksheets;sheets.load("items/name");await c.sync();const target=sheets.add(sheetName("Сборка"));target.load("name");let row=0,count=0;for(const ws of sheets.items){const used=ws.getUsedRangeOrNullObject();used.load(["isNullObject","values","rowCount","columnCount"]);await c.sync();if(used.isNullObject)continue;target.getCell(row,0).values=[[`Лист: ${ws.name}`]];target.getCell(row,0).format.font.bold=true;row++;target.getRangeByIndexes(row,0,used.rowCount,used.columnCount).values=used.values;row+=used.rowCount+2;count++;}target.getUsedRange().format.autofitColumns();target.activate();await c.sync();show("sheets-result",`Собрано листов: ${count}\nЛист: ${target.name}`);});}

async function splitSheet(){await run("Разделение листа",async c=>{const r=c.workbook.getSelectedRange(),sheets=c.workbook.worksheets;r.load(["values","formulas","rowCount","columnCount"]);sheets.load("items/name");await c.sync();const col=+document.getElementById("split-column").value-1;if(col<0||col>=r.columnCount)throw new Error("Неверный столбец.");const groups=new Map(),used=new Set(sheets.items.map(x=>x.name.toLocaleLowerCase()));r.values.slice(1).forEach((row,i)=>{const k=String(row[col]||"Пусто");if(!groups.has(k))groups.set(k,[]);groups.get(k).push(r.formulas[i+1]);});for(const [k,rows] of groups){const ws=sheets.add(uniqueSheetName(k,used));ws.getRangeByIndexes(0,0,rows.length+1,r.columnCount).formulas=[r.formulas[0],...rows];ws.getUsedRange().format.autofitColumns();}await c.sync();show("sheets-result",`Создано листов: ${groups.size}`);});}

async function createSheets(){await run("Создание листов",async c=>{const names=document.getElementById("sheet-names").value.split(";").map(x=>x.trim()).filter(Boolean),sheets=c.workbook.worksheets;if(!names.length)throw new Error("Введите имена через точку с запятой.");sheets.load("items/name");await c.sync();const used=new Set(sheets.items.map(x=>x.name.toLocaleLowerCase()));names.forEach(x=>sheets.add(uniqueSheetName(x,used)));await c.sync();show("sheets-result",`Создано листов: ${names.length}`);});}

async function buildPrompts(){await run("Создание промптов",async c=>{const r=c.workbook.getSelectedRange();r.load(["values","rowCount","columnCount"]);await c.sync();const type=document.getElementById("prompt-template").value,templates={proofread:"Исправь грамматические, орфографические и пунктуационные ошибки. Сохрани смысл и порядок: ",translate:"Переведи на английский язык: ",summary:"Кратко перескажи основные мысли: ",sentiment:"Оцени тональность как плохо, нейтрально или хорошо. Ответь только категорией: ",classify:"Классифицируй обращение: статус заказа, возврат, характеристики продукта, техническая проблема или другое. Ответь только категорией: ",dates:"Извлеки все даты и верни их в формате ДД.ММ.ГГГГ: ",rewrite:"Перепиши текст другими словами, сохранив смысл: "},rows=r.values.map(row=>[templates[type]+String(row[0]??"")]),target=r.getCell(0,r.columnCount).getResizedRange(rows.length-1,0);target.values=rows;target.format.autofitColumns();await c.sync();show("ai-result",`Создано промптов: ${rows.length}. Данные никуда не отправлялись.`);});}

