function defaultFormulaContext(){return{address:"A1:A10",range:"A1:A10",first:"A1",last:"A10",firstColumn:"A1:A10",lastColumn:"A1:A10",rows:10,columns:1,headers:[],hasHeaders:false};}
function columnLetters(index){let value=index+1,result="";while(value){value--;result=String.fromCharCode(65+value%26)+result;value=Math.floor(value/26);}return result;}
function formulaContextFromRange(address,rows,columns,headers,hasHeaders=false){const range=address.includes("!")?address.slice(address.lastIndexOf("!")+1):address,parts=range.replace(/\$/g,"").split(":"),first=parts[0],last=parts[1]||parts[0],match=first.match(/([A-Z]+)(\d+)/i),startColumn=match?match[1].toUpperCase():"A",startRow=match?Number(match[2]):1,startIndex=[...startColumn].reduce((n,ch)=>n*26+ch.charCodeAt(0)-64,0)-1,endColumn=columnLetters(startIndex+columns-1),endRow=startRow+rows-1,dataStartRow=hasHeaders&&rows>1?startRow+1:startRow;return{address,range,first,last,firstColumn:`${startColumn}${dataStartRow}:${startColumn}${endRow}`,lastColumn:`${endColumn}${dataStartRow}:${endColumn}${endRow}`,rows,columns,headers,hasHeaders};}
function renderFormulaLibrary(){const search=(document.getElementById("formula-search").value||"").trim().toLocaleLowerCase(),category=document.getElementById("formula-category").value,list=document.getElementById("formula-library"),selected=list.value;const items=FORMULA_LIBRARY.filter(item=>(category==="all"||item.category===category)&&(!search||`${item.name} ${item.description} ${item.keywords}`.toLocaleLowerCase().includes(search)));list.innerHTML=items.map(item=>`<option value="${item.id}">${escapeHtml(item.name)}</option>`).join("");if(items.length){list.value=items.some(x=>x.id===selected)?selected:items[0].id;selectLibraryFormula();}else{document.getElementById("formula-preview").value="";show("formula-description","Ничего не найдено.");}}
function selectLibraryFormula(){const item=FORMULA_LIBRARY.find(x=>x.id===document.getElementById("formula-library").value);if(!item)return;const context=formulaContext||defaultFormulaContext();document.getElementById("formula-preview").value=item.build(context);document.getElementById("formula-confirm").checked=false;show("formula-description",`${item.name}\n${item.description}`);}
async function readFormulaContext(){await run("Контекст формулы",async c=>{const r=c.workbook.getSelectedRange();r.load(["address","rowCount","columnCount","values"]);await c.sync();const hasHeaders=document.getElementById("formula-has-headers")?.checked===true,headers=hasHeaders?(r.values[0]||[]).slice(0,20).map(value=>String(value??"")).filter(Boolean):[];formulaContext=formulaContextFromRange(r.address,r.rowCount,r.columnCount,headers,hasHeaders);show("formula-context",`Диапазон: ${r.address}\nРазмер: ${r.rowCount} × ${r.columnCount}\nЗаголовки: ${hasHeaders?(headers.join(" | ")||"первая строка пуста"):"нет"}`);selectLibraryFormula();});}
async function insertLibraryFormula(){const formula=document.getElementById("formula-preview").value.trim();if(!formula.startsWith("=")){setStatus("Формула должна начинаться со знака =.",true);return;}if(!document.getElementById("formula-confirm").checked){setStatus("Подтвердите проверку формулы перед вставкой.",true);return;}await run("Вставка формулы из библиотеки",async c=>{const selected=c.workbook.getSelectedRange(),target=selected.getCell(0,0);target.load(["address","values","formulas","rowCount","columnCount"]);await c.sync();const existing=target.formulas[0]?.[0];if(existing!==""&&existing!==null)throw new Error(`Целевая ячейка ${target.address} не пустая. Выберите отдельную пустую ячейку для результата.`);if(formulaContext&&formulaRangeContainsCell(formulaContext.address,target.address))throw new Error(`Ячейка ${target.address} входит в исходный диапазон ${formulaContext.address}. После чтения контекста выберите пустую ячейку вне таблицы.`);if(formulaReferencesCell(formula,target.address))throw new Error(`Формула ссылается на целевую ячейку ${target.address} и может создать циклическую ссылку.`);const b=await backupFormulaSheet(c,target,"Резерв_формула");target.formulas=[[formula]];await c.sync();show("formula-ai-result",`Формула проверена и вставлена в ${target.address}.\nРезервная копия исходного листа: ${b.sheet}`);document.getElementById("formula-confirm").checked=false;});}
function formulaCellParts(address){const clean=String(address||"").replace(/\$/g,""),bang=clean.lastIndexOf("!"),sheet=bang>=0?clean.slice(0,bang).replace(/^'|'$/g,"").replace(/''/g,"'"):"",cell=(bang>=0?clean.slice(bang+1):clean).split(":")[0],match=cell.match(/^([A-Z]+)(\d+)$/i);if(!match)return null;return{sheet:sheet.toLocaleLowerCase(),column:[...match[1].toUpperCase()].reduce((n,ch)=>n*26+ch.charCodeAt(0)-64,0),row:Number(match[2]),a1:`${match[1].toUpperCase()}${Number(match[2])}`};}
function formulaRangeContainsCell(rangeAddress,cellAddress){const bang=String(rangeAddress).lastIndexOf("!"),sheet=bang>=0?String(rangeAddress).slice(0,bang):"",range=bang>=0?String(rangeAddress).slice(bang+1):String(rangeAddress),ends=range.replace(/\$/g,"").split(":"),start=formulaCellParts(`${sheet}!${ends[0]}`),end=formulaCellParts(`${sheet}!${ends[1]||ends[0]}`),cell=formulaCellParts(cellAddress);return Boolean(start&&end&&cell&&start.sheet===cell.sheet&&cell.row>=Math.min(start.row,end.row)&&cell.row<=Math.max(start.row,end.row)&&cell.column>=Math.min(start.column,end.column)&&cell.column<=Math.max(start.column,end.column));}
function formulaReferencesCell(formula,cellAddress){const cell=formulaCellParts(cellAddress);return Boolean(cell&&new RegExp(`(^|[^A-Z0-9_])\\$?${cell.a1.replace(/([A-Z]+)(\d+)/,"$1\\$?$2")}(?![A-Z0-9_])`,"i").test(formula));}
const insertLibraryFormulaValidated=insertLibraryFormula;
insertLibraryFormula=async function(){if(!formulaContext){setStatus("Сначала выделите исходную таблицу и нажмите «Считать контекст выделения».",true);return;}return insertLibraryFormulaValidated();};
function scoreFormula(item,request){const text=request.toLocaleLowerCase();return item.keywords.split(/\s+/).reduce((score,word)=>score+(text.includes(word)?2:0),0)+(text.includes(item.name.toLocaleLowerCase())?4:0);}
function recommendFormula(){const request=document.getElementById("formula-request").value.trim();if(!request){show("formula-ai-result","Опишите задачу обычными словами.");return;}const ranked=FORMULA_LIBRARY.map(item=>({item,score:scoreFormula(item,request)})).sort((a,b)=>b.score-a.score),best=ranked[0];if(!best||best.score===0){show("formula-ai-result","Точного локального шаблона не найдено. Используйте «Подготовить безопасный AI-запрос».");return;}document.getElementById("formula-library").value=best.item.id;document.getElementById("formula-preview").value=best.item.build(formulaContext||defaultFormulaContext());document.getElementById("formula-confirm").checked=false;show("formula-ai-result",`Подобрано: ${best.item.name}\n${best.item.description}\nПроверьте адреса и критерии перед вставкой.`);}
function explainFormulaText(formula){const descriptions={SUM:"суммирует значения",AVERAGE:"вычисляет среднее",MEDIAN:"находит медиану",COUNTIF:"считает по условию",SUMIF:"суммирует по условию",IF:"проверяет условие",IFERROR:"обрабатывает ошибку",XLOOKUP:"выполняет поиск",INDEX:"возвращает значение по позиции",MATCH:"находит позицию",TRIM:"удаляет лишние пробелы",TEXTJOIN:"объединяет текст",TODAY:"возвращает текущую дату",DAYS:"считает дни между датами",UNIQUE:"возвращает уникальные значения",SORT:"сортирует массив",FILTER:"фильтрует массив"},functions=[...formula.matchAll(/([A-Z][A-Z0-9.]*)\s*\(/gi)].map(match=>match[1].toUpperCase()),refs=[...formula.matchAll(/\$?[A-Z]{1,3}\$?\d+(?::\$?[A-Z]{1,3}\$?\d+)?/gi)].map(match=>match[0]);return`Формула: ${formula}\nФункции: ${functions.map(name=>`${name} — ${descriptions[name]||"выполняет вычисление"}`).join("; ")||"не обнаружены"}\nСсылки: ${[...new Set(refs)].join(", ")||"не обнаружены"}`;}
async function explainSelectedFormula(){await run("Объяснение формулы",async c=>{const cell=c.workbook.getSelectedRange().getCell(0,0);cell.load(["address","formulas"]);await c.sync();const formula=cell.formulas[0][0];if(typeof formula!=="string"||!formula.startsWith("="))throw new Error("В первой ячейке выделения нет формулы.");show("formula-ai-result",explainFormulaText(formula));});}
async function buildFormulaAiPrompt(){if(!formulaContext)await readFormulaContext();const request=document.getElementById("formula-request").value.trim()||"Предложи подходящую формулу",preview=document.getElementById("formula-preview").value.trim(),context=formulaContext||defaultFormulaContext(),prompt=`Ты — эксперт по формулам Microsoft Excel. Задача: ${request}. Контекст без значений ячеек: диапазон ${context.address}, размер ${context.rows} × ${context.columns}. Заголовки: ${context.hasHeaders?context.headers.join(" | ")||"первая строка пуста":"в выделении заголовков нет"}. Текущий вариант: ${preview||"нет"}. Верни одну формулу Excel в английских именах функций, затем кратко объясни её и укажи ограничения. Не выдумывай значения ячеек.`;let copied=false;try{await navigator.clipboard.writeText(prompt);copied=true;}catch{}show("formula-ai-result",`${copied?"Безопасный AI-запрос скопирован.":"Скопируйте запрос вручную:"}\n\n${prompt}`);}

function initializeFormulaAiControls(){const anchor=document.getElementById("formula-ai-prompt"),readButton=document.getElementById("formula-read-context");if(!anchor||document.getElementById("formula-ai-configure"))return;anchor.textContent="Скопировать безопасный AI-запрос";if(readButton&&!document.getElementById("formula-has-headers")){const label=document.createElement("label"),checkbox=document.createElement("input");checkbox.id="formula-has-headers";checkbox.type="checkbox";label.append(checkbox,document.createTextNode(" Первая строка выделения содержит заголовки"));readButton.parentNode.insertBefore(label,readButton);}const configure=document.createElement("button"),generate=document.createElement("button");configure.id="formula-ai-configure";configure.className="secondary desktop-only companion-required";configure.textContent="Настроить OpenAI через локальный мост";configure.onclick=configureFormulaAi;generate.id="formula-ai-generate";generate.className="primary desktop-only companion-required";generate.textContent="Получить формулу от AI";generate.onclick=generateFormulaWithAi;anchor.parentNode.insertBefore(configure,anchor);anchor.parentNode.insertBefore(generate,anchor);renderEnvironment();}
async function configureFormulaAi(){if(!desktopState.bridge&&!(await checkCompanion(true))){show("formula-ai-result","Локальный мост не подключён.");return;}desktopBusy=true;toggle(true);show("formula-ai-result","Откройте нативное окно настройки ключа…");try{const result=await companionRequest("commands",{method:"POST",body:JSON.stringify({command:"configure-ai",source:"office-addin",version:"2.8.1"}),timeoutMs:0});show("formula-ai-result",result.message||"Настройка завершена.");addHistory("Формулы + AI: настройка",result.ok!==false,result.message||"");}catch(error){show("formula-ai-result",`Настройка AI не завершена: ${error.message}`);}finally{desktopBusy=false;toggle(false);renderEnvironment();}}
async function generateFormulaWithAi(){const task=document.getElementById("formula-request").value.trim();if(!task){show("formula-ai-result","Сначала опишите задачу.");return;}if(!formulaContext)await readFormulaContext();if(!desktopState.bridge&&!(await checkCompanion(true))){show("formula-ai-result","Для AI требуется локальный мост.");return;}const context=formulaContext||defaultFormulaContext();desktopBusy=true;toggle(true);show("formula-ai-result","AI подготавливает формулу. Значения ячеек не отправляются…");try{const result=await companionRequest("commands",{method:"POST",body:JSON.stringify({command:"ai-formula",source:"office-addin",version:"2.8.1",ai:{task,address:context.address,rows:context.rows,columns:context.columns,headers:context.headers,hasHeaders:context.hasHeaders,currentFormula:document.getElementById("formula-preview").value.trim()}}),timeoutMs:90000});if(!result.ok){show("formula-ai-result",result.message||"AI не вернул формулу.");return;}document.getElementById("formula-preview").value=result.formula;document.getElementById("formula-confirm").checked=false;const usageText=recordAiUsage(result.usage);show("formula-ai-result",`AI предложил формулу (${result.model||"OpenAI"}):\n${result.formula}\n\n${result.explanation||""}${result.warnings?`\nПредупреждение: ${result.warnings}`:""}${usageText?`\n\n${usageText}`:""}\n\nПроверьте формулу перед вставкой.`);addHistory("Формулы + AI: генерация",true,`${task}${usageText?`\n${usageText.split("\n")[0]}`:""}`);}catch(error){show("formula-ai-result",`AI-запрос не выполнен: ${error.message}`);}finally{desktopBusy=false;toggle(false);renderEnvironment();}}
setTimeout(initializeFormulaAiControls,0);
function aiRequestWord(value){const n=value%100;return n>=11&&n<=14?"запросов":value%10===1?"запрос":value%10>=2&&value%10<=4?"запроса":"запросов";}
function getAiUsageTotal(){return JSON.parse(localStorage.getItem("eda-ai-usage")||'{"requests":0,"inputTokens":0,"outputTokens":0,"estimatedCostUsd":0}');}
function recordAiUsage(usage){if(!usage)return"";const input=Number(usage.inputTokens)||0,output=Number(usage.outputTokens)||0,cost=Number(usage.estimatedCostUsd)||0,total=getAiUsageTotal();total.requests+=1;total.inputTokens+=input;total.outputTokens+=output;total.estimatedCostUsd+=cost;total.lastRequestAt=new Date().toISOString();localStorage.setItem("eda-ai-usage",JSON.stringify(total));renderAiUsageSummary();return`Расход запроса: входные токены — ${input}; выходные — ${output}; ≈ $${cost.toFixed(6)}.\nЛокальный итог: ${total.requests} ${aiRequestWord(total.requests)}; ≈ $${total.estimatedCostUsd.toFixed(6)}.`;}
function renderAiUsageSummary(){const panel=document.getElementById("panel-history");if(!panel)return;let box=document.getElementById("ai-usage-summary");if(!box){box=document.createElement("div");box.id="ai-usage-summary";box.className="result-box";panel.insertBefore(box,panel.querySelector("button"));const reset=document.createElement("button");reset.id="reset-ai-usage";reset.className="secondary";reset.textContent="Сбросить статистику расходов AI";reset.onclick=()=>confirmDestructiveButton("reset-ai-usage","Нажмите ещё раз: сбросить расходы AI",()=>{localStorage.removeItem("eda-ai-usage");renderAiUsageSummary();setStatus("Статистика расходов AI сброшена.");});const exportButton=document.createElement("button");exportButton.id="export-ai-journal";exportButton.className="secondary";exportButton.textContent="Скачать журнал и расходы";exportButton.onclick=exportAiJournal;panel.insertBefore(reset,box.nextSibling);panel.insertBefore(exportButton,reset.nextSibling);}const total=getAiUsageTotal(),last=total.lastRequestAt?new Date(total.lastRequestAt).toLocaleString():"—";box.textContent=`Расходы AI\nЗапросы: ${total.requests}\nВходные токены: ${total.inputTokens}\nВыходные токены: ${total.outputTokens}\nОриентировочная стоимость: $${Number(total.estimatedCostUsd||0).toFixed(6)}\nПоследний AI-запрос: ${last}`;}
function exportAiJournal(){const payload={product:"Excel Data Assistant",version:APP_VERSION,exportedAt:new Date().toISOString(),aiUsage:getAiUsageTotal(),operations:history},blob=new Blob([JSON.stringify(payload,null,2)],{type:"application/json;charset=utf-8"}),a=document.createElement("a");a.href=URL.createObjectURL(blob);a.download=`excel-data-assistant-journal-${Date.now()}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);setStatus("Журнал операций и статистика расходов сохранены.");}
const destructiveConfirmations=new Map();
function confirmDestructiveButton(id,warning,action){const button=document.getElementById(id);if(!button)return;const now=Date.now(),armed=destructiveConfirmations.get(id);if(armed&&now-armed.time<5000){clearTimeout(armed.timer);destructiveConfirmations.delete(id);button.textContent=armed.original;button.classList.remove("danger");action();return;}if(armed)clearTimeout(armed.timer);const original=button.textContent;button.textContent=warning;button.classList.add("danger");setStatus("Для подтверждения нажмите эту же кнопку ещё раз в течение 5 секунд.",true);const timer=setTimeout(()=>{destructiveConfirmations.delete(id);button.textContent=original;button.classList.remove("danger");setStatus("Удаление отменено.");},5000);destructiveConfirmations.set(id,{time:now,timer,original});}
setTimeout(renderAiUsageSummary,0);

function detectEnvironment(){const p=Office.context.platform||"unknown",names={PC:"Windows",Mac:"macOS",OfficeOnline:"Excel Online",iOS:"iOS",Android:"Android",Universal:"Universal"},levels=["1.16","1.15","1.14","1.13","1.12","1.11","1.10","1.9","1.8","1.7","1.6","1.5","1.4","1.3","1.2","1.1"],api=levels.find(v=>Office.context.requirements?.isSetSupported("ExcelApi",v))||"базовый";desktopState.platform=String(p);desktopState.mode=names[p]||String(p);desktopState.api=api;desktopState.isDesktop=p===Office.PlatformType.PC||p===Office.PlatformType.Mac;renderEnvironment();return desktopState;}
function renderEnvironment(){document.getElementById("desktop-platform").textContent=desktopState.mode;document.getElementById("desktop-mode").textContent=desktopState.isDesktop?"Локальный Excel":"Веб-режим";document.getElementById("desktop-api").textContent=`ExcelApi ${desktopState.api}`;document.getElementById("desktop-bridge").textContent=desktopState.bridge?"Подключён":"Не подключён";document.getElementById("desktop-bridge-version").textContent=desktopState.bridgeVersion;document.getElementById("desktop-bridge-uptime").textContent=desktopState.bridge?formatUptime(desktopState.uptime):"—";document.getElementById("desktop-excel-process").textContent=desktopState.bridge?(desktopState.excelRunning?"Запущен":"Не найден"):"—";document.getElementById("desktop-summary").textContent=desktopState.isDesktop?"Настольный Excel обнаружен. Office.js-функции доступны; системные команды требуют локальный мост.":"Сейчас открыт Excel Online. Общие функции работают, Desktop Pro будет активен в локальном Excel.";document.querySelectorAll(".desktop-only").forEach(x=>x.disabled=!desktopState.isDesktop);document.querySelectorAll(".companion-required").forEach(x=>x.disabled=!desktopState.isDesktop||!desktopState.bridge);}
function formatUptime(seconds){const total=Math.max(0,Number(seconds)||0),h=Math.floor(total/3600),m=Math.floor(total%3600/60),s=Math.floor(total%60);return h?`${h} ч ${m} мин`:(m?`${m} мин ${s} сек`:`${s} сек`);}
async function refreshDesktopStatus(silent=false){detectEnvironment();const connected=await checkCompanion(true);if(!silent)show("desktop-result",connected?"Сведения о среде и локальном мосте обновлены.":"Сведения о среде обновлены. Локальный мост не подключён.");return connected;}
async function exportDiagnostics(){await refreshDesktopStatus(true);const data={product:"Excel Data Assistant",version:"2.3.2",time:new Date().toISOString(),host:Office.context.host,platform:desktopState.platform,mode:desktopState.mode,excelApi:desktopState.api,desktop:desktopState.isDesktop,companion:{connected:desktopState.bridge,version:desktopState.bridgeVersion,uptimeSeconds:desktopState.uptime,excelRunning:desktopState.excelRunning},userAgent:navigator.userAgent},blob=new Blob([JSON.stringify(data,null,2)],{type:"application/json;charset=utf-8"}),a=document.createElement("a");a.href=URL.createObjectURL(blob);a.download=`excel-assistant-diagnostics-${Date.now()}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);show("desktop-result","Диагностический отчёт подготовлен. Токен, персональные данные и содержимое книги не включены.");}
async function companionRequest(path,options={}){const timeoutMs=options.timeoutMs??2500,{timeoutMs:_timeoutMs,...fetchOptions}=options,controller=new AbortController(),timer=timeoutMs>0?setTimeout(()=>controller.abort(),timeoutMs):null,headers={"Content-Type":"application/json",...(fetchOptions.headers||{})};if(desktopState.token)headers["X-EDA-Token"]=desktopState.token;try{const response=await fetch(`https://127.0.0.1:47831/v1/${path}`,{...fetchOptions,headers,signal:controller.signal});if(!response.ok){const error=new Error(`HTTP ${response.status}`);error.status=response.status;throw error;}return await response.json();}finally{if(timer)clearTimeout(timer);}}
async function checkCompanion(silent=false){detectEnvironment();if(!desktopState.isDesktop){if(!silent)show("desktop-result","Локальный мост проверяется только в настольном Excel.");return false;}if(!silent)toggle(true);try{desktopState.token="";const info=await companionRequest("health");desktopState.bridge=info?.product==="Excel Data Assistant Companion";desktopState.token=desktopState.bridge?String(info.sessionToken||""):"";desktopState.bridgeVersion=desktopState.bridge?String(info.version||"—"):"—";desktopState.uptime=Number(info.uptimeSeconds)||0;desktopState.excelRunning=Boolean(info.excelRunning);if(!silent)show("desktop-result",desktopState.bridge?`Локальный мост подключён. Версия: ${info.version||"не указана"}`:"Получен ответ неизвестного локального сервиса.");return desktopState.bridge;}catch(_e){desktopState.bridge=false;desktopState.token="";desktopState.bridgeVersion="—";desktopState.uptime=0;desktopState.excelRunning=false;if(!silent)show("desktop-result","Локальный мост пока не установлен или не запущен.");return false;}finally{renderEnvironment();if(!silent)toggle(false);}}
async function autoConnectCompanion(){if(desktopBusy||desktopState.bridge||!desktopState.isDesktop)return;for(let attempt=0;attempt<12&&!desktopState.bridge;attempt++){await checkCompanion(true);if(!desktopState.bridge)await new Promise(resolve=>setTimeout(resolve,1000));}}
async function desktopCommand(command){const names={"folder-import":"Объединить книги из папки","batch-export":"Массовый экспорт листов","power-query":"Запустить локальный сценарий Power Query","convert-xls":"Преобразовать XLS в XLSX","combine-csv":"Объединить CSV-файлы из папки","split-workbook":"Разделить книгу на файлы по листам","export-pdf":"Экспортировать листы в PDF","inspect-links":"Найти внешние ссылки и подключения","backup-workbook":"Создать резервную копию книги"},name=names[command]||command;if(!desktopState.isDesktop){show("desktop-result","Локальные функции доступны только в Excel для Windows.");return;}if(desktopBusy){show("desktop-result","Другая локальная операция уже выполняется. Завершите её перед новым запуском.");return;}if(!desktopState.bridge&&!(await checkCompanion(true))){show("desktop-result","Локальный мост не запущен. Запустите Desktop Companion и повторите команду.");return;}desktopBusy=true;toggle(true);show("desktop-result",`Выполняется: ${name}. Завершите выбор файлов в открывшемся окне…`);const request=()=>companionRequest("commands",{method:"POST",body:JSON.stringify({command,source:"office-addin",version:"2.6.0"}),timeoutMs:0});try{let result;try{result=await request();}catch(error){if(error.status!==401)throw error;if(!(await checkCompanion(true)))throw error;result=await request();}const message=result.message||`${name}: готово.`;show("desktop-result",message);addHistory(`Desktop Pro: ${name}`,result.ok!==false,message);}catch(e){desktopState.bridge=false;const message=`${name}: операция не завершена (${e.message}).`;show("desktop-result",message);addHistory(`Desktop Pro: ${name}`,false,e.message);}finally{desktopBusy=false;renderEnvironment();toggle(false);}}
async function restartCompanion(){if(desktopBusy)return;if(!desktopState.bridge&&!(await checkCompanion(true))){show("desktop-result","Локальный мост не запущен.");return;}desktopBusy=true;toggle(true);show("desktop-result","Безопасный перезапуск локального моста…");try{await companionRequest("commands",{method:"POST",body:JSON.stringify({command:"restart-bridge",source:"office-addin",version:"2.3.0"}),timeoutMs:5000});desktopState.bridge=false;renderEnvironment();await new Promise(resolve=>setTimeout(resolve,1800));let connected=false;for(let attempt=0;attempt<8&&!connected;attempt++){connected=await checkCompanion(true);if(!connected)await new Promise(resolve=>setTimeout(resolve,700));}const message=connected?"Локальный мост успешно перезапущен и подключён.":"Мост перезапускается дольше обычного. Нажмите «Проверить локальный мост» через несколько секунд.";show("desktop-result",message);addHistory("Desktop Pro: безопасный перезапуск",connected,message);}catch(e){desktopState.bridge=false;show("desktop-result",`Не удалось перезапустить мост: ${e.message}`);addHistory("Desktop Pro: безопасный перезапуск",false,e.message);}finally{desktopBusy=false;renderEnvironment();toggle(false);}}

async function backup(c,r,prefix){const ws=c.workbook.worksheets.add(sheetName(prefix));ws.load("name");const copy=ws.getRangeByIndexes(0,0,r.rowCount,r.columnCount);copy.copyFrom(r,"All");await c.sync();lastBackup={sheet:ws.name,target:r.address};localStorage.setItem("eda-backup",JSON.stringify(lastBackup));return lastBackup;}
async function backupFormulaSheet(c,target,prefix){const source=target.worksheet,used=source.getUsedRangeOrNullObject();source.load("name");used.load(["address","rowCount","columnCount","isNullObject"]);await c.sync();const ws=c.workbook.worksheets.add(sheetName(prefix));ws.load("name");if(!used.isNullObject){ws.getRangeByIndexes(0,0,used.rowCount,used.columnCount).copyFrom(used,"All");}await c.sync();lastBackup={sheet:ws.name,target:used.isNullObject?target.address:used.address};localStorage.setItem("eda-backup",JSON.stringify(lastBackup));return lastBackup;}
async function restoreLast(){lastBackup=lastBackup||JSON.parse(localStorage.getItem("eda-backup")||"null");if(!lastBackup){setStatus("Нет резервной копии.",true);return;}await run("Восстановление",async c=>{const src=c.workbook.worksheets.getItem(lastBackup.sheet).getUsedRange(),target=rangeFromAddress(c,lastBackup.target);src.load(["rowCount","columnCount"]);await c.sync();target.clear("All");target.getCell(0,0).getResizedRange(src.rowCount-1,src.columnCount-1).copyFrom(src,"All");await c.sync();setStatus(`Восстановлено из ${lastBackup.sheet}.`);});}
function rangeFromAddress(c,address){const bang=address.lastIndexOf("!");if(bang<0)throw new Error(`Некорректный адрес резервной копии: ${address}`);const sheet=address.slice(0,bang).replace(/^'|'$/g,"").replace(/''/g,"'"),range=address.slice(bang+1);return c.workbook.worksheets.getItem(sheet).getRange(range);}
function addHistory(action,ok,detail=""){history.unshift({time:new Date().toISOString(),action,ok,detail});history=history.slice(0,50);saveHistory();renderHistory();}function saveHistory(){localStorage.setItem("eda-history",JSON.stringify(history));}function renderHistory(){const lang=document.documentElement.lang||"ru";document.getElementById("history-list").innerHTML=history.length?history.map(x=>`<div class="history-item"><strong>${x.ok?"✓":"✕"} ${escapeHtml(x.action)}</strong><time>${new Date(x.time).toLocaleString(lang)}</time>${escapeHtml(x.detail||"")}</div>`).join(""):I18N[lang].historyEmpty;}
async function run(action,fn){toggle(true);progress(5);try{await Excel.run(fn);if(action)addHistory(action,true);setStatus(statusEl.classList.contains("error")?"Готово.":statusEl.textContent);}catch(e){console.error(e);setStatus(e.message||"Ошибка Excel.",true);if(action)addHistory(action,false,e.message);}finally{progress(100);setTimeout(()=>document.getElementById("progress").classList.add("hidden"),350);toggle(false);}}
function progress(n){const p=document.getElementById("progress");p.classList.remove("hidden");document.getElementById("progress-bar").style.width=`${n}%`;document.getElementById("progress-text").textContent=`${n}%`;}
function setStatus(m,error=false){statusEl.textContent=m;statusEl.classList.toggle("error",error);}function toggle(v){document.querySelectorAll("button").forEach(b=>b.disabled=v);}function show(id,t){const e=document.getElementById(id);e.textContent=t;e.classList.remove("hidden");}
function safeSheetName(name){return String(name||"Лист").replace(/[\\/\?\*\[\]:]/g,"_").trim().slice(0,31)||"Лист";}function uniqueSheetName(name,used){const base=safeSheetName(name);let candidate=base,n=2;while(used.has(candidate.toLocaleLowerCase())){const suffix=`_${n++}`;candidate=base.slice(0,31-suffix.length)+suffix;}used.add(candidate.toLocaleLowerCase());return candidate;}
function median(a){if(!a.length)return null;const m=Math.floor(a.length/2);return a.length%2?a[m]:(a[m-1]+a[m])/2;}function keyValue(v,cs=false){return typeof v==="string"?`s:${cs?v.trim():v.trim().toLocaleLowerCase()}`:`${typeof v}:${String(v)}`;}function rowKey(r,cs=false){return JSON.stringify(r.map(x=>keyValue(x,cs)));}function findDuplicateKeys(rows,k){const s=new Set(),d=new Set();rows.forEach(r=>{const x=keyValue(r[k]);if(s.has(x))d.add(String(r[k]));else s.add(x);});return [...d];}function pad(r,n){return Array.from({length:n},(_,i)=>r[i]??"");}function padHeaders(r,n,p){return Array.from({length:n},(_,i)=>`${p}: ${r[i]??`Столбец ${i+1}`}`);}function sheetName(p){return `${p}_${new Date().toISOString().slice(11,23).replace(/[:.]/g,"")}`.slice(0,31);}function styleHeader(r){r.format.fill.color="#217346";r.format.font.color="#FFFFFF";r.format.font.bold=true;}function inferType(v,fmt){if(/[%]/.test(fmt))return "Процент";if(/[dmy]/i.test(fmt))return "Дата/время";if(v.every(x=>x===""||typeof x==="number"))return "Число";if(v.every(x=>x===""||typeof x==="boolean"))return "Логический";return "Смешанный/текст";}function escapeHtml(s){return String(s).replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]));}
